import { parseUnits } from 'viem'

let _snarkjs = null
let _buildPoseidon = null
let _poseidon = null

export const zkReady = (async () => {
  const [sn, { buildPoseidon }] = await Promise.all([
    import('snarkjs'),
    import('circomlibjs'),
  ])
  _snarkjs = sn
  _buildPoseidon = buildPoseidon
})()

const TREE_DEPTH = 20
const ZERO_VALUE = 14744269619966411208579211824598458697587494354926760081771325075741142829156n // poseidon([0,0]) on BN254 — matches contract POSEIDON_ZERO

export async function poseidon(inputs) {
  if (!_poseidon) { await zkReady; _poseidon = await _buildPoseidon() }
  return BigInt(_poseidon.F.toString(_poseidon(inputs)))
}

// zeros[d] = hash of empty subtree at depth d — must match contract
let _zeros = null
async function getZeros() {
  if (_zeros) return _zeros
  _zeros = [ZERO_VALUE]
  for (let i = 1; i < TREE_DEPTH; i++) {
    _zeros.push(await poseidon([_zeros[i-1], _zeros[i-1]]))
  }
  return _zeros
}

export async function buildMerkleTree(leaves) {
  const zeros = await getZeros()
  const layers = [leaves.map(BigInt)]
  for (let d = 0; d < TREE_DEPTH; d++) {
    const cur = layers[d]
    const len = Math.ceil(cur.length / 2) || 1
    const next = []
    for (let i = 0; i < len; i++) {
      const l = cur[2*i]   !== undefined ? cur[2*i]   : zeros[d]
      const r = cur[2*i+1] !== undefined ? cur[2*i+1] : zeros[d]
      next.push(await poseidon([l, r]))
    }
    layers.push(next)
  }
  return { layers, root: layers[TREE_DEPTH][0] }
}

export async function getMerkleProof(tree, leafIndex) {
  const zeros = await getZeros()
  const pathElements = []
  const pathIndices  = []
  let idx = leafIndex
  for (let d = 0; d < TREE_DEPTH; d++) {
    const layer   = tree.layers[d]
    const isRight = idx % 2
    const sibling = isRight
      ? (layer[idx-1] ?? zeros[d])
      : (layer[idx+1] ?? zeros[d])
    pathElements.push(sibling)
    pathIndices.push(isRight)
    idx = Math.floor(idx / 2)
  }
  return { pathElements, pathIndices }
}

export async function generateTicket(token, amount, chainId, decimals = 18) {
  const secret    = BigInt('0x' + crypto.getRandomValues(new Uint8Array(31)).reduce((s,b)=>s+b.toString(16).padStart(2,'0'),''))
  const nullifier = BigInt('0x' + crypto.getRandomValues(new Uint8Array(31)).reduce((s,b)=>s+b.toString(16).padStart(2,'0'),''))
  const amountBig     = parseUnits(amount, decimals)
  const commitment    = await poseidon([secret, nullifier, amountBig])
  const nullifierHash = await poseidon([nullifier])
  return { secret: secret.toString(), nullifier: nullifier.toString(), nullifierHash: nullifierHash.toString(), commitment: commitment.toString(), token, amount, decimals, chainId }
}

export async function generateProof(note, recipient, tree, leafIndex, relayer = '0x0000000000000000000000000000000000000000', fee = 0n, onProgress) {
  const secret        = BigInt(note.secret)
  const nullifier     = BigInt(note.nullifier)
  const nullifierHash = await poseidon([nullifier])
  const amountBig     = parseUnits(note.amount, note.decimals ?? 18)
  const { pathElements, pathIndices } = await getMerkleProof(tree, leafIndex)

  const SNARK_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617n
  if (BigInt(recipient) >= SNARK_FIELD) throw new Error('recipient address out of SNARK field')

  const input = {
    root:          tree.root.toString(),
    nullifierHash: nullifierHash.toString(),
    recipient:     BigInt(recipient).toString(),
    amount:        amountBig.toString(),
    relayer:       BigInt(relayer).toString(),
    fee:           fee.toString(),
    secret:        secret.toString(),
    nullifier:     nullifier.toString(),
    pathElements:  pathElements.map(String),
    pathIndices:   pathIndices.map(Number),
  }

  const wasmPath = '/zk/withdraw_js/withdraw_v10.wasm'
  const zkeyPath = '/zk/withdraw_final_v10.zkey'
  onProgress?.(10)
  const wtns = { type: 'mem' }
  await _snarkjs.wtns.calculate(input, wasmPath, wtns)
  onProgress?.(60)
  const { proof } = await _snarkjs.groth16.prove(zkeyPath, wtns)
  onProgress?.(100)

  return {
    a: [BigInt(proof.pi_a[0]), BigInt(proof.pi_a[1])],
    b: [[BigInt(proof.pi_b[0][1]), BigInt(proof.pi_b[0][0])],
        [BigInt(proof.pi_b[1][1]), BigInt(proof.pi_b[1][0])]],
    c: [BigInt(proof.pi_c[0]), BigInt(proof.pi_c[1])],
    nullifierHash,
    root: tree.root,
  }
}
